sys_script.script:
(function executeRule(current, previous) {
  if (current.opened_by.nil()) current.opened_by = gs.getUserID();
  if (current.state.nil()) current.state = 1;
  if (current.number.nil()) {
    var seq = 1000;
    var last = new GlideRecord('x_snc_ptag_engage_engagement_request');
    last.orderByDesc('number'); last.setLimit(1); last.query();
    if (last.next()) {
      var s = last.number.toString();
      if (s.indexOf('PTAG') === 0) { var n = parseInt(s.substring(4), 10); if (!isNaN(n)) seq = n; }
    }
    current.number = 'PTAG' + ('0000000' + (seq + 1)).slice(-7);
  }
  if (current.status_token.nil()) {
    current.status_token = ('' + gs.generateGUID() + gs.generateGUID()).replace(/-/g, '').substring(0, 24);
  }
  if (current.assignment_group.nil() && !current.practice.nil()) {
    /* I5: auto-assign by practice - keys are the intake app's 4 practice names.
       Fallback preserved: unknown practice -> same-name group lookup; no
       matching active group -> assignment_group stays empty. */
    var PRACTICE_GROUPS = {
      'AI Platform & Data': 'AI Platform & Data',
      'Autonomous Workforce': 'Autonomous Workforce',
      'CRM': 'CRM',
      'Security Risk and Governance': 'Security Risk and Governance'
    };
    var pname = current.practice.getDisplayValue();
    var gname = PRACTICE_GROUPS.hasOwnProperty(pname) ? PRACTICE_GROUPS[pname] : pname;
    var grp = new GlideRecord('sys_user_group');
    grp.addQuery('name', gname);
    grp.addActiveQuery(); grp.query();
    if (grp.next()) current.assignment_group = grp.getUniqueValue();
  }
})(current, previous);
